// Real browser + HTTP checks against the disposable acceptance stack only.
import assert from "node:assert/strict";
import { readFile, writeFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import { parseJSON, stringifyJSON, ExactNumber } from "../../../admin-frontend/src/legacy/numbers.js";
if (process.env.CREDIT_ENGINE_UI_TEST !== "1") throw Error("Explicitly isolated services required");
const origin = process.env.CREDIT_ENGINE_UI_ORIGIN || "http://localhost:18084";
const scoring = process.env.CREDIT_ENGINE_SCORING_URL;
const output = process.env.CREDIT_ENGINE_UI_OUTPUT;
const { chromium } = await import(pathToFileURL(process.env.PLAYWRIGHT_MODULE).href);
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 1440, height: 1000 }, acceptDownloads: true });
const page = await context.newPage(), errors = [];
page.on("pageerror", error => errors.push(error.message));
page.on("console", event => { if (/Content Security Policy|Refused to/.test(event.text())) errors.push(event.text()); });
let csrf;
const api = async (method, path, body, expectedStatus = 200) => {
  const response = await context.request.fetch(origin + path, { method, headers: { Origin: origin, "X-CSRF-Token": csrf || "", "Content-Type": "application/json" }, ...(body === undefined ? {} : { data: stringifyJSON(body) }) });
  const raw = await response.text();
  assert.equal(response.status(), expectedStatus, path + " " + raw.slice(0, 600));
  return raw ? parseJSON(raw) : null;
};
const evaluate = async request => {
  const response = await context.request.post(scoring + "/api/v1/decisions", { data: stringifyJSON(request), headers: { "Content-Type": "application/json" } });
  const raw = await response.text(); assert.equal(response.status(), 200, raw.slice(0, 800));
  return { data: parseJSON(raw), version: response.headers()["x-scoring-model-version"], sha: response.headers()["x-scoring-model-sha256"] };
};
const click = name => page.getByRole("button", { name, exact: true }).click();
const visible = locator => locator.waitFor({ state: "visible", timeout: 25000 });
try {
  await page.goto(origin);
  await page.getByLabel("Логин", { exact: true }).fill("editor");
  await page.getByLabel("Пароль", { exact: true }).fill("fictional-admin-password");
  await click("Войти");
  await visible(page.getByRole("heading", { name: "Модели скоринга", exact: true }));
  csrf = (await api("GET", "/api/admin/v1/auth/session")).csrf_token;
  if (process.argv[2] === "restart") {
    const saved = JSON.parse(await readFile(output + "/live-activation.json", "utf8"));
    const current = (await api("GET", "/api/admin/v1/active-models")).find(a => a.borrower_type === "SOLE_PROPRIETOR");
    assert.equal(current.version, saved.version);
    const attempt = await evaluate({ application_id: "post-restart-" + Date.now(), borrower: { id: "borrower", type: "SOLE_PROPRIETOR" } });
    assert.equal(attempt.version, saved.version); assert.equal(attempt.sha, saved.sha);
    await api("PUT", "/api/admin/v1/active-models/SOLE_PROPRIETOR", { version: "ip-v2", expected_activation_revision: current.revision, reason: "Acceptance restores baseline after restart verification" });
    await writeFile(output + "/live-activation-restart.json", JSON.stringify({ passed: true, version: saved.version, sha: saved.sha }));
    console.log("live activation persists after scoring restart: passed");
  } else {
    const source = await api("GET", "/api/admin/v1/models/ip-v2");
    const active = (await api("GET", "/api/admin/v1/active-models")).find(a => a.borrower_type === "SOLE_PROPRIETOR");
    assert.equal(active.version, "ip-v2");
    const fixture = parseJSON(await readFile(new URL("../../../testdata/decisions/uc04_ip_approved.json", import.meta.url), "utf8"));
    fixture.request.scoring.ip.owner_age = new ExactNumber("40");
    fixture.request.application_id = "baseline-live-" + Date.now();
    const before = await evaluate(fixture.request);
    assert.ok(before.data.score); assert.equal(before.version, "ip-v2");
    const retryID = "documents-live-" + Date.now();
    const incomplete = await evaluate({ application_id: retryID, borrower: fixture.request.borrower });
    assert.equal(incomplete.data.status, "NEED_INFO"); assert.equal(incomplete.version, "ip-v2");
    const definition = source.definition;
    const version = "ip-live-ui-" + Date.now().toString(36);
    definition.version = version;
    definition.criteria[0].cases[4].points = new ExactNumber("10");
    definition.parameters.find(p => p.id === "owner_age").number.lower.value = new ExactNumber("0e0");
    await page.locator('input[type="file"][accept=".json,application/json"]').setInputFiles({ name: "live-model.json", mimeType: "application/json", buffer: Buffer.from(stringifyJSON(definition, true)) });
    const dialog = page.getByRole("dialog");
    await dialog.getByLabel("Новая версия", { exact: true }).fill(version);
    await dialog.getByLabel("Основание", { exact: true }).fill("Import exact JSON and change age scale");
    await dialog.getByRole("button", { name: "Создать черновик", exact: true }).click();
    await visible(page.getByText("Модель прошла проверку.", { exact: true }));
    const id = page.url().split("#draft/")[1].split("/")[0];
    const card = page.locator(".criterion-card").filter({ has: page.getByRole("heading", { name: definition.criteria[0].title, exact: true }) });
    await card.locator("summary").click();
    assert.equal(await page.getByLabel("Баллы IP_Q01 band_5", { exact: true }).inputValue(), "10");
    const toggle = page.getByRole("checkbox", { name: "Учитывать в баллах IP_Q09", exact: true });
    await toggle.locator("..").click();
    assert.equal(await toggle.isChecked(),false);
    await page.getByLabel("Основание сохранения / применения", { exact: true }).fill("Save intermediate invalid weights");
    await click("Сохранить ревизию");
    await visible(page.getByText("Черновик · ревизия 2", { exact: true }));
    assert.equal(await page.getByRole("button", { name: "Применить", exact: true }).isDisabled(), true);
    await api("POST", "/api/admin/v1/drafts/" + id + "/apply", { expected_revision: 2, expected_activation_revision: active.revision, reason: "Must reject invalid weights" }, 422);
    await page.getByRole("checkbox", { name: "Учитывать в баллах IP_Q09", exact: true }).locator("..").click();
    await page.getByLabel("Основание сохранения / применения", { exact: true }).fill("Restore strict 750/250 maximums");
    await click("Сохранить ревизию");
    await visible(page.getByText("Черновик · ревизия 3", { exact: true }));
    const downloadPromise = page.waitForEvent("download");
    await page.locator(".page-heading").getByRole("button", { name: "Скачать JSON", exact: true }).click();
    const download = await downloadPromise; await download.saveAs(output + "/live-export.json");
    const exported = await readFile(output + "/live-export.json", "utf8"); assert.match(exported, /0e0/);
    await page.getByLabel("Основание сохранения / применения", { exact: true }).fill("Apply JSON without restart");
    await click("Применить");
    await visible(page.getByRole("status").filter({ hasText: version }));
    fixture.request.application_id = retryID;
    const after = await evaluate(fixture.request);
    assert.equal(after.version, version); assert.equal(after.data.score.model, version);
    assert.equal(Number(String(before.data.score.raw_total)) - Number(String(after.data.score.raw_total)), 15);
    const published = await api("GET", "/api/admin/v1/models/" + version); assert.equal(after.sha, published.definition_sha256);
    await api("PUT", "/api/admin/v1/active-models/SOLE_PROPRIETOR", { version: "ip-v2", expected_activation_revision: active.revision, reason: "Concurrent stale activation must fail" }, 409);
    await api("PUT", "/api/admin/v1/drafts/" + id, { expected_revision: 1, definition, reason: "Stale editor must fail" }, 409);
    await page.getByRole("navigation", { name: "Основная навигация" }).getByRole("link", { name: "Неиспользуемые данные", exact: true }).click();
    await page.getByLabel("Источник данных", { exact: true }).selectOption("MARKETPLACES");
    await visible(page.getByRole("cell", { name: "Не передаётся в скоринговые признаки", exact: true }).first());
    await page.getByLabel("Тип заёмщика данных", { exact: true }).selectOption("LEGAL_ENTITY");
    await visible(page.getByRole("heading", { name: "Данные data-collector · Юридическое лицо", exact: true }));
    await page.screenshot({ path: output + "/unused-data-desktop.png", fullPage: true });
    assert.deepEqual(errors, []);
    await writeFile(output + "/live-activation.json", JSON.stringify({ passed: true, version, sha: after.sha, before: String(before.data.score.raw_total), after: String(after.data.score.raw_total), checks: ["JSON import/export exact exponent", "score scale", "disabled criteria and invalid saved draft", "validation before apply", "apply without restart", "new model after NEED_INFO", "actual response SHA", "revision conflicts", "unused catalog by source and borrower"] }, null, 2));
    console.log("live JSON activation: passed");
  }
} catch (error) {
  await page.screenshot({ path: output + "/live-activation-failure.png", fullPage: true });
  await writeFile(output + "/live-activation-failure.txt", errors.join("\n") + "\n" + await page.locator("body").innerText());
  throw error;
} finally { await browser.close(); }
